import { useEffect, useMemo, useRef, useState } from "react";
import WI from "./WebIcons";
import type { WebPage } from "./types";
import { IRAN_PROVINCES } from "./bannerLocations";

const BASE=((import.meta as any).env?.VITE_BANNER_API_URL as string|undefined)?.replace(/\/$/,"")??"";
const FA=(v:unknown)=>String(v??"").replace(/\d/g,d=>"۰۱۲۳۴۵۶۷۸۹"[+d]);
const EN=(v:unknown)=>String(v??"").replace(/[۰-۹]/g,d=>String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)));
const fmt=(v:number|null,cur="IRR",mode?:string)=>mode==="free"?"رایگان":mode==="swap"?"معاوضه":mode==="negotiable"||v==null?"توافقی":`${FA(Number(v).toLocaleString())} ${cur==="IRR"?"تومان":cur}`;

async function api(path:string,init:RequestInit={}) {
  const token=localStorage.getItem("anpardaz:accessToken")??localStorage.getItem("accessToken")??"";
  const r=await fetch(BASE+path,{...init,headers:{...(init.body?{"content-type":"application/json"}:{}),...(init.headers??{}),...(token?{authorization:"Bearer "+token}:{})},cache:"no-store"});
  const body=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error(String(body?.error??"banner_request_failed"));
  return body;
}
function mediaUrl(id:number|string){return BASE+"/api/v1/banner/media/"+encodeURIComponent(String(id));}
function categoryOptions(categories:any[]){const byParent=new Map<string,any[]>();for(const c of categories){const k=String(c.parent_id??"root");const a=byParent.get(k)??[];a.push(c);byParent.set(k,a);}for(const a of byParent.values())a.sort((x,y)=>Number(x.sort_order)-Number(y.sort_order)||Number(x.id)-Number(y.id));const out:any[]=[];const walk=(parent:string|null,depth=0)=>{for(const c of byParent.get(String(parent??"root"))??[]){out.push({...c,_depth:depth});walk(String(c.id),depth+1);}};walk(null);return out;}
type Listing=any; type Ticket=any; type Conversation=any;

interface Props{onNavigate:(p:WebPage)=>void;isLoggedIn:boolean;onAuthRequired:()=>void;}

export default function WebBanner({onNavigate,isLoggedIn,onAuthRequired}:Props){
  const [section,setSection]=useState<"home"|"favorites"|"recent"|"messages"|"notifications"|"my-listings"|"account"|"tickets"|"post"|"search"|"support"|"terms"|"postchi"|"edit"|"seller-profile">("home");
  const [listings,setListings]=useState<Listing[]>([]);
  const [categories,setCategories]=useState<any[]>([]);
  const [favorites,setFavorites]=useState<Set<string>>(new Set());
  const [favoriteListings,setFavoriteListings]=useState<Listing[]>([]);
  const [selected,setSelected]=useState<Listing|null>(null);
  const [publicSellerId,setPublicSellerId]=useState<string|null>(null);
  const [editingListing,setEditingListing]=useState<Listing|null>(null);
  const [query,setQuery]=useState("");
  const [city,setCity]=useState("");
  const [category,setCategory]=useState("");
  const [sort,setSort]=useState("newest");
  const [minPrice,setMinPrice]=useState("");
  const [maxPrice,setMaxPrice]=useState("");
  const [page,setPage]=useState(1);
  const [total,setTotal]=useState(0);
  const [searchHistory,setSearchHistory]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem("anpardaz:banner:web-search-history")||"[]").slice(0,12)}catch{return []}});
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");
  const [tickets,setTickets]=useState<Ticket[]>([]);
  const [ticket,setTicket]=useState<any|null>(null);
  const [conversations,setConversations]=useState<Conversation[]>([]);
  const [conversation,setConversation]=useState<any|null>(null);
  const [notifications,setNotifications]=useState<any[]>([]);
  const [postchiEvents,setPostchiEvents]=useState<any[]>([]);
  const [profile,setProfile]=useState<any|null>(null);
  const [myListings,setMyListings]=useState<Listing[]>([]);const [recentViews,setRecentViews]=useState<Listing[]>([]);

  const searchRequestId=useRef(0);
  const loadHome=async()=>{
    const requestId=++searchRequestId.current;
    setLoading(true);setError("");
    try{
      const q=new URLSearchParams();if(query.trim())q.set("q",query.trim());if(city.trim())q.set("city",city.trim());if(category)q.set("categoryId",category);if(minPrice)q.set("minPrice",minPrice);if(maxPrice)q.set("maxPrice",maxPrice);q.set("sort",sort==="price-asc"?"price_asc":sort==="price-desc"?"price_desc":"newest");q.set("page",String(page));q.set("limit","24");
      const [l,c]=await Promise.all([api("/api/v1/banner/listings?"+q.toString()),api("/api/v1/banner/categories")]);
      if(requestId!==searchRequestId.current)return;
      setListings(l.listings??[]);setTotal(Number(l.total??0));setCategories(c.categories??[]);
      if(isLoggedIn){const f=await api("/api/v1/banner/me/favorites");if(requestId!==searchRequestId.current)return;setFavorites(new Set((f.listings??[]).map((x:any)=>String(x.id))));setFavoriteListings(f.listings??[])}else{setFavorites(new Set());setFavoriteListings([])}
    }catch(e){if(requestId===searchRequestId.current)setError(e instanceof Error?e.message:"خطا در دریافت آگهی‌ها")}finally{if(requestId===searchRequestId.current)setLoading(false)}
  };
  const loadPrivate=async()=>{
    if(!isLoggedIn){setTickets([]);setNotifications([]);setPostchiEvents([]);setProfile(null);setConversations([]);setMyListings([]);setRecentViews([]);setFavoriteListings([]);setFavorites(new Set());return;}
    setLoading(true);setError("");
    try{
      const [f,t,n,p,m,ml,rv,pc]=await Promise.all([
        api("/api/v1/banner/me/favorites"),api("/api/v1/banner/me/tickets"),api("/api/v1/banner/me/notifications"),
        api("/api/v1/banner/me"),api("/api/v1/banner/me/conversations"),api("/api/v1/banner/me/listings"),api("/api/v1/banner/me/recent-views"),api("/api/v1/banner/me/postchi")
      ]);
      setFavorites(new Set((f.listings??[]).map((x:any)=>String(x.id))));setFavoriteListings(f.listings??[]);setTickets(t.tickets??[]);setNotifications(n.notifications??[]);setPostchiEvents(pc.events??[]);setProfile(p.profile??null);setConversations(m.conversations??[]);setMyListings(ml.listings??[]);setRecentViews(rv.listings??[]);
    }catch(e){setError(e instanceof Error?e.message:"خطا در دریافت اطلاعات حساب")}finally{setLoading(false)}
  };
  useEffect(()=>{void loadHome()},[query,city,category,minPrice,maxPrice,sort,page,isLoggedIn]);
  useEffect(()=>{if(isLoggedIn)void loadPrivate()},[isLoggedIn]);

  const filtered=useMemo(()=>listings,[listings]);
  const rememberSearch=(raw=query)=>{const value=raw.trim();if(!value)return;setSearchHistory(old=>{const next=[value,...old.filter(x=>x!==value)].slice(0,12);try{localStorage.setItem("anpardaz:banner:web-search-history",JSON.stringify(next))}catch{}return next});setPage(1)};
  const protectedNav=(s:typeof section)=>{if(!isLoggedIn){onAuthRequired();return;}setSection(s);setSelected(null);};

  const toggleFavorite=async(id:string)=>{
    if(!isLoggedIn){onAuthRequired();return;}
    try{const r=await api("/api/v1/banner/listings/"+encodeURIComponent(id)+"/favorite",{method:"POST"});setFavorites(p=>{const n=new Set(p);r.favorite?n.add(id):n.delete(id);return n;});setFavoriteListings(p=>r.favorite?(p.some(x=>String(x.id)===id)?p:[...p,...listings.filter(x=>String(x.id)===id)]):p.filter(x=>String(x.id)!==id));}catch(e){setError(e instanceof Error?e.message:"favorite_failed")}
  };
  const openListing=async(x:Listing)=>{try{if(isLoggedIn){void api("/api/v1/banner/me/recent-views/"+x.id,{method:"POST",body:"{}"}).then(async()=>{const r=await api("/api/v1/banner/me/recent-views");setRecentViews(r.listings??[])}).catch(()=>{});}const d=await api("/api/v1/banner/listings/"+x.id);setSelected({...x,...d.listing,media:d.media??[]});}catch(e){setError(e instanceof Error?e.message:"listing_failed")}};

  const nav=[
    ["home","آگهی‌ها"],["search","جستجو"],["favorites","نشان‌شده‌ها"],["recent","آخرین مشاهده‌ها"],["postchi","پستچی و اعلان‌ها"],["messages","چت و تماس"],["notifications","اعلان‌ها"],
    ["my-listings","آگهی‌های من"],["account","حساب کاربری"],["tickets","تیکت‌های پشتیبانی"],["support","راهنما"],["terms","قوانین"]
  ] as const;

  return <div className="w-fade" dir="rtl" style={{minHeight:"calc(100vh - var(--w-header))"}}><style>{`.ab-web-shell,.ab-web-shell button,.ab-web-shell input,.ab-web-shell select,.ab-web-shell textarea{font-family:"Vazirmatn",sans-serif}.ab-detail-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.8fr);gap:18px;margin-top:12px}.ab-web-toolbar{flex-wrap:wrap}.ab-web-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:0 0 14px}.ab-web-pagination{display:flex;align-items:center;justify-content:center;gap:12px;padding:18px 0;color:var(--w-muted);font-size:12px}.ab-web-pagination button:disabled{opacity:.4;cursor:not-allowed}.ab-web-nav{display:flex;flex-direction:column}@media(max-width:900px){.ab-detail-grid{grid-template-columns:1fr}.ab-web-shell{padding:0 14px!important}.ab-web-nav{width:100%!important;min-height:0!important;border-left:0!important;border-bottom:1px solid var(--w-border);display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;padding:12px 0!important}.ab-web-nav button{margin:0!important;justify-content:center!important;font-size:12px}.ab-web-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.ab-web-toolbar{min-width:0!important;display:grid!important;grid-template-columns:1fr 1fr}.ab-web-toolbar input:first-child{grid-column:1/-1}.ab-web-filters{grid-template-columns:1fr}.ab-web-pagination{gap:7px;flex-wrap:wrap}.ab-web-pagination button{min-width:68px}.ab-price-modes{grid-template-columns:repeat(2,minmax(0,1fr))!important}.ab-detail-grid{min-width:0}.ab-detail-grid>*{min-width:0}}`}</style>
    <div style={{background:"var(--w-surface)",borderBottom:"1px solid var(--w-border)"}}>
      <div style={{maxWidth:1480,margin:"0 auto",padding:"10px 20px",display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
        <button onClick={()=>{setSection("home");setSelected(null)}} style={{display:"flex",alignItems:"center",gap:8,border:0,background:"transparent",cursor:"pointer",fontWeight:900,fontSize:16}}><span style={{width:30,height:30,borderRadius:8,background:"rgba(232,53,78,.12)",display:"grid",placeItems:"center",color:"#e8354e"}}><WI n="banner" s={16}/></span>آن بنر</button>
        <div className="ab-web-toolbar" style={{display:"flex",gap:8,flex:1,minWidth:260}}>
          <input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} onKeyDown={e=>{if(e.key==="Enter"){rememberSearch();setSection("home");setSelected(null)}}} onFocus={()=>{setSection("home");setSelected(null)}} className="w-input" placeholder="جستجو در همه آگهی‌ها..."/>
          <select value={city} onChange={e=>{setCity(e.target.value);setPage(1)}} className="w-input" style={{maxWidth:190}}><option value="">همه شهرها</option>{IRAN_PROVINCES.map(p=><optgroup key={p.id} label={p.name}>{p.cities.map(x=><option key={x.id} value={x.name}>{x.name}</option>)}</optgroup>)}</select>
          <select value={category} onChange={e=>{setCategory(e.target.value);setPage(1)}} className="w-input" style={{maxWidth:190}}><option value="">همه دسته‌ها</option>{categoryOptions(categories).map(c=><option key={c.id} value={c.id}>{"— ".repeat(c._depth)}{c.name}</option>)}</select>
        </div>
        <button className="w-btn w-btn-primary" onClick={()=>{rememberSearch();protectedNav("post")}}><WI n="plus" s={14}/> ثبت آگهی</button>
        <button className="w-btn w-btn-ghost" onClick={()=>onNavigate("home")}><WI n="arrow-right" s={14}/> آن پرداز</button>
      </div>
    </div>
    <div className="ab-web-shell" style={{maxWidth:1480,margin:"0 auto",padding:"0 20px",display:"flex",gap:18,flexWrap:"wrap"}}>
      <aside className="ab-web-nav" style={{width:190,flexShrink:0,paddingTop:14,borderLeft:"1px solid var(--w-border)",minHeight:"calc(100vh - var(--w-header) - 55px)"}}>
        {nav.map(([id,label])=><button key={id} onClick={()=>id==="home"?(setSection("home"),setSelected(null)):protectedNav(id as any)} className={section===id?"w-btn w-btn-primary":"w-btn w-btn-ghost"} style={{width:"100%",justifyContent:"flex-start",marginBottom:7}}>{label}</button>)}
      </aside>
      <main style={{flex:1,minWidth:0,padding:"18px 0 50px"}}>
        {error&&<div className="w-card" style={{padding:12,marginBottom:12,color:"#dc2626"}}>{error}</div>}
        {selected&&<Detail listing={selected} favorite={favorites.has(String(selected.id))} onBack={()=>setSelected(null)} onFavorite={()=>void toggleFavorite(String(selected.id))} isLoggedIn={isLoggedIn} onAuthRequired={onAuthRequired} onOpenSeller={id=>{setPublicSellerId(id);setSection("seller-profile");setSelected(null)}}/>}
        {!selected&&section==="home"&&<><div className="ab-web-filters"><input className="w-input" inputMode="numeric" value={minPrice} onChange={e=>{setMinPrice(EN(e.target.value).replace(/[^0-9]/g,""));setPage(1)}} placeholder="حداقل قیمت (تومان)"/><input className="w-input" inputMode="numeric" value={maxPrice} onChange={e=>{setMaxPrice(EN(e.target.value).replace(/[^0-9]/g,""));setPage(1)}} placeholder="حداکثر قیمت (تومان)"/><select className="w-input" value={sort} onChange={e=>{setSort(e.target.value);setPage(1)}}><option value="newest">جدیدترین</option><option value="price-asc">ارزان‌ترین</option><option value="price-desc">گران‌ترین</option></select><button className="w-btn w-btn-ghost" onClick={()=>{setMinPrice("");setMaxPrice("");setSort("newest");setCity("");setCategory("");setQuery("");setPage(1)}}>پاک‌کردن فیلترها</button></div><Home listings={filtered} loading={loading} favorites={favorites} onOpen={openListing} onFavorite={toggleFavorite}/><div className="ab-web-pagination"><span>{FA(total)} آگهی</span><button className="w-btn w-btn-ghost" disabled={page<=1||loading} onClick={()=>setPage(p=>Math.max(1,p-1))}>قبلی</button><span>صفحه {FA(page)} از {FA(Math.max(1,Math.ceil(total/24)))}</span><button className="w-btn w-btn-ghost" disabled={page>=Math.ceil(total/24)||loading} onClick={()=>setPage(p=>p+1)}>بعدی</button></div></>}
        {section==="recent"&&<Home listings={recentViews} loading={loading} favorites={favorites} onOpen={openListing} onFavorite={toggleFavorite} title="آخرین مشاهده‌ها"/>}
        {section==="favorites"&&<Home listings={favoriteListings} loading={loading} favorites={favorites} onOpen={openListing} onFavorite={toggleFavorite} title="علاقه‌مندی‌های من"/>}
        {section==="my-listings"&&<MyListings listings={myListings} onOpen={x=>setSelected({...x,media:(x.media_ids??[]).map((id:number)=>({id}))})} onEdit={x=>{setEditingListing(x);setSection("edit")}} onRefresh={loadPrivate}/>}
        {section==="edit"&&editingListing&&<EditListing listing={editingListing} onCancel={()=>setSection("my-listings")} onDone={()=>{setEditingListing(null);setSection("my-listings");void loadPrivate()}}/>}
        {section==="account"&&<Account profile={profile} onRefresh={loadPrivate}/>}
        {section==="notifications"&&<Notifications items={notifications} onRefresh={loadPrivate}/>}
        {section==="messages"&&<Messages conversations={conversations} conversation={conversation} setConversation={setConversation} onRefresh={loadPrivate}/>}
        {section==="tickets"&&<Tickets tickets={tickets} ticket={ticket} setTicket={setTicket} onRefresh={loadPrivate}/>}
        {section==="post"&&<Post categories={categories} onDone={()=>{setSection("my-listings");void loadPrivate()}}/>}
        {section==="seller-profile"&&publicSellerId&&<SellerProfile identityId={publicSellerId} onOpenListing={x=>{void openListing(x)}} onBack={()=>setSection("home")}/>}
        {section==="search"&&<SearchPanel history={searchHistory} query={query} setQuery={setQuery} onSearch={(value)=>{if(value!==undefined)setQuery(value);rememberSearch(value??query);setSection("home");setPage(1)}} onClear={()=>{setSearchHistory([]);localStorage.removeItem("anpardaz:banner:web-search-history")}}/>}
        {section==="postchi"&&<Postchi items={postchiEvents} onRefresh={loadPrivate} onOpenListing={async(id)=>{try{const d=await api("/api/v1/banner/listings/"+encodeURIComponent(id));setSelected({...d.listing,media:d.media??[]});setSection("home")}catch(e){setError(e instanceof Error?e.message:"آگهی در دسترس نیست")}}} onOpenConversation={async(id)=>{try{setConversation(await api("/api/v1/banner/conversations/"+encodeURIComponent(id)));setSection("messages")}catch(e){setError(e instanceof Error?e.message:"مکالمه در دسترس نیست")}}}/>}
        {section==="support"&&<SupportInfo/>}
        {section==="terms"&&<TermsInfo/>}
      </main>
    </div>
  </div>;
}

function Home({listings,loading,favorites,onOpen,onFavorite,title="آخرین آگهی‌ها"}:{listings:Listing[];loading:boolean;favorites:Set<string>;onOpen:(x:Listing)=>void;onFavorite:(id:string)=>void;title?:string}){
 return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div><h1 style={{margin:0,fontSize:22,fontWeight:900}}>{title}</h1><div style={{fontSize:12,color:"var(--w-muted)",marginTop:5}}>داده‌ها مستقیماً از سرویس آن بنر خوانده می‌شوند.</div></div><span style={{fontSize:12,color:"var(--w-muted)"}}>{FA(listings.length)} آگهی</span></div>
 {loading&&!listings.length?<div className="w-card" style={{padding:30,textAlign:"center"}}>در حال دریافت...</div>:!listings.length?<div className="w-card" style={{padding:40,textAlign:"center"}}>آگهی واقعی برای این فیلتر وجود ندارد.</div>:<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(240px,1fr))",gap:12}}>{listings.map(x=><div key={x.id} className="w-card" style={{overflow:"hidden"}}>
   <div style={{height:180,background:"var(--w-card2)",display:"grid",placeItems:"center",overflow:"hidden"}}>{x.media_ids?.[0]?<img src={mediaUrl(x.media_ids[0])} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<WI n="banner" s={34}/>}</div>
   <div style={{padding:13}}><div style={{display:"flex",justifyContent:"space-between",gap:8}}><button onClick={()=>onOpen(x)} style={{border:0,background:"transparent",padding:0,cursor:"pointer",textAlign:"right",fontWeight:800,fontSize:14,color:"var(--w-text)"}}>{x.title}</button><button onClick={()=>void onFavorite(String(x.id))} style={{border:0,background:"transparent",cursor:"pointer",color:favorites.has(String(x.id))?"#e8354e":"var(--w-muted)"}}><WI n={favorites.has(String(x.id))?"heartFill":"heart"} s={18}/></button></div><div style={{fontSize:11,color:"var(--w-muted)",marginTop:7}}>{x.category_name??"—"} · {x.city}</div><div style={{fontWeight:900,marginTop:10}}>{fmt(x.price,x.currency,x.price_mode)}</div></div>
 </div>)}</div>}
 </div>;
}

function Detail({listing,favorite,onBack,onFavorite,isLoggedIn,onAuthRequired,onOpenSeller}:{listing:Listing;favorite:boolean;onBack:()=>void;onFavorite:()=>void;isLoggedIn:boolean;onAuthRequired:()=>void;onOpenSeller:(id:string)=>void}){
 const [message,setMessage]=useState("");const [sent,setSent]=useState(false);const [phone,setPhone]=useState("");const [reported,setReported]=useState(false);
 const send=async()=>{if(!isLoggedIn){onAuthRequired();return;}if(!message.trim())return;try{await api("/api/v1/banner/conversations",{method:"POST",body:JSON.stringify({listingId:Number(listing.id),message:message.trim()})});setMessage("");setSent(true)}catch(e){setSent(false)}};
 const contact=async()=>{if(!isLoggedIn){onAuthRequired();return;}try{const r=await api("/api/v1/banner/listings/"+listing.id+"/contact");setPhone(r.phone??"")}catch{}};
 const report=async()=>{if(!isLoggedIn){onAuthRequired();return;}const reason=window.prompt("دلیل گزارش تخلف");if(!reason?.trim())return;try{await api("/api/v1/banner/listings/"+listing.id+"/report",{method:"POST",body:JSON.stringify({reason:reason.trim()})});setReported(true)}catch{}};
 const share=async()=>{const url=window.location.href;if(navigator.share)await navigator.share({title:listing.title,url}).catch(()=>{});else await navigator.clipboard?.writeText(url)};
 return <div><button className="w-btn w-btn-ghost" onClick={onBack}>بازگشت</button><div className="ab-detail-grid"><div className="w-card" style={{overflow:"hidden"}}><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:6,padding:6}}>{(listing.media??[]).map((m:any)=><img key={m.id} src={mediaUrl(m.id)} alt="" style={{width:"100%",height:220,objectFit:"cover",borderRadius:10}}/>)}{!(listing.media??[]).length&&<div style={{height:220,display:"grid",placeItems:"center"}}><WI n="banner" s={42}/></div>}</div><div style={{padding:18}}><h1 style={{margin:"0 0 10px",fontSize:24}}>{listing.title}</h1><p style={{lineHeight:1.9,color:"var(--w-muted)"}}>{listing.description}</p><div style={{fontSize:20,fontWeight:900,marginTop:15}}>{fmt(listing.price,listing.currency,listing.price_mode)}</div><div style={{fontSize:12,color:"var(--w-muted)",marginTop:8}}>{listing.category_name} · {listing.city} · {listing.condition}</div>{listing.attributes&&Object.keys(listing.attributes).length>0&&<div style={{marginTop:16,paddingTop:12,borderTop:"1px solid var(--w-border)"}}><b style={{fontSize:12}}>مشخصات</b><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:8,marginTop:8}}>{Object.entries(listing.attributes).map(([k,v])=><div key={k} style={{padding:8,background:"var(--w-card2)",borderRadius:8,fontSize:11}}><b>{k}</b><div>{String(v)}</div></div>)}</div></div>}</div></div><div className="w-card" style={{padding:18,height:"fit-content"}}><div style={{fontWeight:900}}>فروشنده</div><button onClick={()=>listing.seller_identity_id&&onOpenSeller(String(listing.seller_identity_id))} disabled={!listing.seller_identity_id} style={{display:"flex",alignItems:"center",gap:10,border:0,background:"transparent",padding:0,marginTop:12,cursor:"pointer",textAlign:"right",width:"100%"}}>{listing.seller_avatar_data_url?<img src={listing.seller_avatar_data_url} alt="" style={{width:42,height:42,borderRadius:14,objectFit:"cover"}}/>:<span style={{width:42,height:42,borderRadius:14,background:"var(--w-card2)",display:"grid",placeItems:"center"}}><WI n="user" s={18}/></span>}<span><b>{listing.seller_display_name??"کاربر آن بنر"}</b><small style={{display:"block",fontSize:10,color:"var(--w-muted)"}}>مشاهده پروفایل و آگهی‌های فروشنده ←</small></span></button><div style={{display:"flex",gap:7,flexWrap:"wrap",marginTop:12}}><button className="w-btn w-btn-ghost" onClick={()=>void share()}>اشتراک‌گذاری</button><button className="w-btn w-btn-ghost" onClick={()=>void contact()}>نمایش تماس</button></div>{phone&&<div style={{marginTop:9,fontWeight:800,direction:"ltr",textAlign:"right"}}>{phone}</div>}<button className="w-btn w-btn-ghost" onClick={onFavorite} style={{marginTop:12}}><WI n={favorite?"heartFill":"heart"} s={15}/> {favorite?"حذف از علاقه‌مندی":"افزودن به علاقه‌مندی"}</button><textarea className="w-input" rows={5} value={message} onChange={e=>setMessage(e.target.value)} placeholder="پیام به فروشنده" style={{marginTop:14}}/><button className="w-btn w-btn-primary" onClick={()=>void send()} style={{marginTop:8,width:"100%",justifyContent:"center"}}>ارسال پیام</button><button className="w-btn w-btn-ghost" onClick={()=>void report()} disabled={reported} style={{marginTop:7,width:"100%",justifyContent:"center"}}>{reported?"گزارش ارسال شد":"گزارش تخلف"}</button>{sent&&<div style={{color:"#059669",fontSize:12,marginTop:8}}>پیام در سرویس آن بنر ثبت شد.</div>}</div></div></div>;
}
function MyListings({listings,onOpen,onEdit,onRefresh}:{listings:Listing[];onOpen:(x:Listing)=>void;onEdit:(x:Listing)=>void;onRefresh:()=>void}){
 const change=async(id:string,status:string)=>{try{await api("/api/v1/banner/listings/"+id,{method:"PATCH",body:JSON.stringify({status})});onRefresh()}catch{}};
 const remove=async(id:string)=>{if(!window.confirm("آیا از حذف این آگهی مطمئن هستید؟"))return;try{await api("/api/v1/banner/listings/"+id,{method:"DELETE"});onRefresh()}catch{}};
 return <div><h2 style={{fontSize:20}}>آگهی‌های من</h2>{!listings.length?<div className="w-card" style={{padding:30}}>هنوز آگهی‌ای ثبت نکرده‌اید.</div>:<div style={{display:"grid",gap:10}}>{listings.map(x=><div key={x.id} className="w-card" style={{padding:14,display:"flex",justifyContent:"space-between",gap:12,alignItems:"center"}}><div><button onClick={()=>onOpen(x)} style={{border:0,background:"transparent",cursor:"pointer",fontWeight:800}}>{x.title}</button><div style={{fontSize:11,color:"var(--w-muted)",marginTop:5}}>{x.status} · {x.city} · {fmt(x.price,x.currency,x.price_mode)}</div></div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}><button className="w-btn w-btn-ghost" onClick={()=>onEdit(x)}>ویرایش</button>{x.status==="pending"&&<span style={{fontSize:11}}>در انتظار تأیید</span>}{x.status==="published"&&<button className="w-btn w-btn-ghost" onClick={()=>void change(String(x.id),"paused")}>توقف</button>}{x.status==="paused"&&<button className="w-btn w-btn-primary" onClick={()=>void change(String(x.id),"pending")}>ارسال مجدد برای بررسی</button>}<button className="w-btn w-btn-ghost" onClick={()=>void remove(String(x.id))}>حذف</button></div></div>)}</div>}</div>;
}

function EditListing({listing,onCancel,onDone}:{listing:Listing;onCancel:()=>void;onDone:()=>void}){
 const [title,setTitle]=useState(listing.title??"");const [description,setDescription]=useState(listing.description??"");const [price,setPrice]=useState(listing.price==null?"":String(listing.price));const [priceMode,setPriceMode]=useState<"fixed"|"negotiable"|"free"|"swap">(listing.price_mode??"fixed");const [city,setCity]=useState(listing.city??"");const [condition,setCondition]=useState(listing.condition??"used");const [contactEnabled,setContactEnabled]=useState(listing.contact_enabled!==false);const [chatEnabled,setChatEnabled]=useState(listing.chat_enabled!==false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 const save=async()=>{if(!title.trim()||!description.trim()||description.length>200||!city.trim()||priceMode==="fixed"&&!price.trim()||(!contactEnabled&&!chatEnabled)){setError("عنوان، توضیحات، شهر، قیمت و حداقل یکی از روش‌های تماس را بررسی کنید.");return;}setBusy(true);setError("");try{await api("/api/v1/banner/listings/"+encodeURIComponent(String(listing.id)),{method:"PATCH",body:JSON.stringify({title:title.trim(),description:description.trim(),priceMode,price:priceMode==="fixed"?Number(EN(price)):null,city:city.trim(),condition,contactEnabled,chatEnabled})});onDone()}catch(e){setError(e instanceof Error?e.message:"ذخیره تغییرات ناموفق بود")}finally{setBusy(false)}};
 return <div className="w-card" style={{padding:22,maxWidth:760}}><h2 style={{marginTop:0}}>ویرایش آگهی</h2><div style={{display:"grid",gap:10}}><input className="w-input" value={title} onChange={e=>setTitle(e.target.value)} maxLength={100} placeholder="عنوان آگهی"/><textarea className="w-input" rows={5} maxLength={200} value={description} onChange={e=>setDescription(e.target.value)} placeholder="توضیحات"/><input className="w-input" value={city} onChange={e=>setCity(e.target.value)} placeholder="شهر"/><div><b style={{fontSize:12}}>نوع قیمت</b><div className="ab-price-modes" style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:7,marginTop:7}}>{([{key:"fixed",label:"ثابت"},{key:"negotiable",label:"توافقی"},{key:"free",label:"رایگان"},{key:"swap",label:"معاوضه"}] as const).map(x=><button key={x.key} type="button" className={priceMode===x.key?"w-btn w-btn-primary":"w-btn w-btn-ghost"} onClick={()=>setPriceMode(x.key)}>{x.label}</button>)}</div>{priceMode==="fixed"&&<input className="w-input" inputMode="numeric" value={price} onChange={e=>setPrice(EN(e.target.value).replace(/[^0-9]/g,""))} placeholder="قیمت به تومان" style={{marginTop:8}}/>}</div><select className="w-input" value={condition} onChange={e=>setCondition(e.target.value)}><option value="new">نو</option><option value="like-new">در حد نو</option><option value="good">خوب</option><option value="used">کارکرده</option><option value="for-parts">قطعات</option></select><div style={{display:"flex",gap:14,flexWrap:"wrap",fontSize:12}}><label><input type="checkbox" checked={contactEnabled} onChange={e=>setContactEnabled(e.target.checked)}/> تماس تلفنی</label><label><input type="checkbox" checked={chatEnabled} onChange={e=>setChatEnabled(e.target.checked)}/> پیام و چت</label></div>{error&&<div style={{color:"#dc2626"}}>{error}</div>}<div style={{display:"flex",gap:8}}><button className="w-btn w-btn-primary" onClick={()=>void save()} disabled={busy}>{busy?"در حال ذخیره...":"ذخیره تغییرات"}</button><button className="w-btn w-btn-ghost" onClick={onCancel} disabled={busy}>انصراف</button></div></div></div>;
}
function Account({profile,onRefresh}:{profile:any;onRefresh:()=>void}){
 const [name,setName]=useState(profile?.display_name??"");const [phone,setPhone]=useState(profile?.phone??"");const [city,setCity]=useState(profile?.city??"");const [avatar,setAvatar]=useState<string>(profile?.avatar_data_url??"");const [avatarBase64,setAvatarBase64]=useState("");const [avatarMime,setAvatarMime]=useState("");const [saved,setSaved]=useState(false);const [error,setError]=useState("");
 useEffect(()=>{setName(profile?.display_name??"");setPhone(profile?.phone??"");setCity(profile?.city??"");setAvatar(profile?.avatar_data_url??"");setAvatarBase64("");setAvatarMime("")},[profile]);
 const chooseAvatar=async(file?:File)=>{if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){setError("تصویر باید JPG، PNG یا WebP و حداکثر ۵ مگابایت باشد.");return;}const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(r.error);r.readAsDataURL(file)});setAvatar(data);setAvatarBase64(data.split(",")[1]??"");setAvatarMime(file.type);setError("")};
 const save=async()=>{setError("");try{await api("/api/v1/banner/me",{method:"PATCH",body:JSON.stringify({displayName:name,city, ...(avatarBase64?{avatarBase64,avatarMime}:{})})});setSaved(true);onRefresh()}catch(e){setError(e instanceof Error?e.message:"ذخیره پروفایل ناموفق بود")}};
 return <div className="w-card" style={{padding:22,maxWidth:650}}><h2 style={{marginTop:0}}>حساب کاربری آن بنر</h2><div style={{display:"grid",gap:12}}><div style={{display:"flex",alignItems:"center",gap:14}}><div style={{width:76,height:76,borderRadius:22,overflow:"hidden",background:"var(--w-card2)",display:"grid",placeItems:"center",border:"1px solid var(--w-border)"}}>{avatar?<img src={avatar} alt="تصویر پروفایل" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<WI n="user" s={28}/>}</div><label className="w-btn w-btn-ghost" style={{cursor:"pointer"}}>انتخاب تصویر<input type="file" accept="image/jpeg,image/png,image/webp" hidden onChange={e=>void chooseAvatar(e.target.files?.[0])}/></label></div><input className="w-input" value={name} onChange={e=>setName(e.target.value)} placeholder="نام و نام‌خانوادگی"/><input className="w-input" value={phone} readOnly placeholder="شماره موبایل" dir="ltr" aria-label="شماره موبایل ثبت‌شده در حساب اصلی"/><input className="w-input" value={city} onChange={e=>setCity(e.target.value)} placeholder="شهر"/>{error&&<div style={{fontSize:12,color:"#dc2626"}}>{error}</div>}<button className="w-btn w-btn-primary" onClick={()=>void save()}>ذخیره پروفایل</button>{saved&&<span style={{fontSize:12,color:"#059669"}}>ذخیره شد.</span>}</div></div>;
}
function Notifications({items,onRefresh}:{items:any[];onRefresh:()=>void}){
 const read=async(id:number)=>{await api("/api/v1/banner/notifications/"+id+"/read",{method:"PATCH",body:"{}"});onRefresh()};
 const all=async()=>{await api("/api/v1/banner/notifications/read-all",{method:"POST",body:"{}"});onRefresh()};
 return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><h2>اعلان‌ها</h2><button className="w-btn w-btn-ghost" onClick={()=>void all()}>همه خوانده شد</button></div>{!items.length?<div className="w-card" style={{padding:30}}>اعلانی وجود ندارد.</div>:items.map(n=><div key={n.id} className="w-card" style={{padding:13,marginBottom:8,cursor:n.read?"default":"pointer"}} onClick={()=>!n.read&&void read(n.id)}><b>{n.title}</b><div style={{fontSize:12,color:"var(--w-muted)",marginTop:5}}>{n.description}</div><div style={{fontSize:10,color:"var(--w-muted)",marginTop:6}}>{n.created_at}</div></div>)}</div>;
}

function BannerChatImage({id,mime}:{id:string;mime?:string}){const [src,setSrc]=useState("");useEffect(()=>{let u="";let dead=false;(async()=>{try{const t=localStorage.getItem("anpardaz:accessToken")??localStorage.getItem("accessToken")??"";const r=await fetch(BASE+"/api/v1/banner/messages/"+encodeURIComponent(id)+"/media",{headers:{authorization:"Bearer "+t},cache:"no-store"});if(!r.ok)return;u=URL.createObjectURL(await r.blob());if(!dead)setSrc(u)}catch{}})();return()=>{dead=true;if(u)URL.revokeObjectURL(u)}},[id]);return src?(mime?.startsWith("audio/")?<audio controls preload="metadata" src={src} style={{maxWidth:260}}/>:<img src={src} alt="تصویر پیام" style={{maxWidth:260,maxHeight:320,borderRadius:10}}/>):<span style={{fontSize:11,color:"var(--w-muted)"}}>در حال دریافت رسانه…</span>}

function Messages({conversations,conversation,setConversation,onRefresh}:{conversations:Conversation[];conversation:any;setConversation:(x:any)=>void;onRefresh:()=>void}){
 const [text,setText]=useState("");const [offerAmount,setOfferAmount]=useState("");const [offerMode,setOfferMode]=useState(false);const [imageBusy,setImageBusy]=useState(false);const [recording,setRecording]=useState(false);const [recordingSecs,setRecordingSecs]=useState(0);const [showStickers,setShowStickers]=useState(false);const [chatError,setChatError]=useState("");const recorder=useRef<MediaRecorder|null>(null);const chunks=useRef<Blob[]>([]);const timer=useRef<ReturnType<typeof setInterval>|null>(null);
 const stickers=["😊","😂","🥰","😎","🤔","👍","👏","🙏","❤️","🎉","🔥","✅","😢","😮","🤝","💪","🌹","🎁","⭐","💯","🚗","🏠","📱","💰","🛒","🎭","🌸","🦋","🍕","☕"];
 const open=async(id:string)=>{try{setChatError("");setConversation(await api("/api/v1/banner/conversations/"+id))}catch(e){setChatError(e instanceof Error?e.message:"دریافت مکالمه ناموفق بود")}};
 const refreshConversation=async()=>{if(!conversation?.conversation?.id)return;setConversation(await api("/api/v1/banner/conversations/"+conversation.conversation.id));onRefresh()};
 const send=async()=>{if(!conversation?.conversation?.id||!text.trim())return;try{await api("/api/v1/banner/conversations/"+conversation.conversation.id+"/messages",{method:"POST",body:JSON.stringify({message:text.trim(),type:"text"})});setText("");setShowStickers(false);await refreshConversation()}catch(e){setChatError(e instanceof Error?e.message:"ارسال پیام ناموفق بود")}};
 const sendSticker=async(value:string)=>{if(!conversation?.conversation?.id)return;try{await api("/api/v1/banner/conversations/"+conversation.conversation.id+"/messages",{method:"POST",body:JSON.stringify({message:value,type:"sticker"})});setShowStickers(false);await refreshConversation()}catch(e){setChatError(e instanceof Error?e.message:"ارسال شکلک ناموفق بود")}};
 const sendOffer=async()=>{const amount=Number(offerAmount.replace(/[^0-9]/g,""));if(!conversation?.conversation?.id||!Number.isSafeInteger(amount)||amount<=0)return;try{await api("/api/v1/banner/conversations/"+conversation.conversation.id+"/messages",{method:"POST",body:JSON.stringify({type:"offer",offerAmount:amount,message:""})});setOfferAmount("");setOfferMode(false);await refreshConversation()}catch(e){setChatError(e instanceof Error?e.message:"ثبت پیشنهاد قیمت ناموفق بود")}};
 const startVoice=async()=>{if(recording||!conversation?.conversation?.id)return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=MediaRecorder.isTypeSupported("audio/webm")?"audio/webm":"audio/ogg";const mr=new MediaRecorder(stream,{mimeType:mime});chunks.current=[];mr.ondataavailable=e=>{if(e.data.size)chunks.current.push(e.data)};mr.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());if(timer.current)clearInterval(timer.current);setRecording(false);setRecordingSecs(0);const blob=new Blob(chunks.current,{type:mime});if(!blob.size||blob.size>8*1024*1024){setChatError("حجم پیام صوتی باید حداکثر ۸ مگابایت باشد.");return;}const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(",")[1]??"");r.onerror=()=>reject(r.error);r.readAsDataURL(blob)});try{await api("/api/v1/banner/conversations/"+conversation.conversation.id+"/messages",{method:"POST",body:JSON.stringify({type:"voice",mediaMime:mime,mediaBase64:data,message:""})});await refreshConversation()}catch(e){setChatError(e instanceof Error?e.message:"ارسال پیام صوتی ناموفق بود")}};recorder.current=mr;mr.start();setRecording(true);setRecordingSecs(0);timer.current=setInterval(()=>setRecordingSecs(x=>x+1),1000)}catch{setChatError("دسترسی به میکروفون ممکن نیست یا مرورگر از ضبط صوت پشتیبانی نمی‌کند.")}};
 const stopVoice=()=>{if(recorder.current&&recorder.current.state!=="inactive")recorder.current.stop()};
 const cancelVoice=()=>{const mr=recorder.current;if(mr&&mr.state!=="inactive"){mr.ondataavailable=null;mr.onstop=()=>{mr.stream.getTracks().forEach(t=>t.stop())};mr.stop()}if(timer.current)clearInterval(timer.current);setRecording(false);setRecordingSecs(0)};
 const sendImage=async(file:File)=>{if(!conversation?.conversation?.id||!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>8*1024*1024){setChatError("تصویر باید JPG، PNG یا WebP و حداکثر ۸ مگابایت باشد.");return;}setImageBusy(true);setChatError("");try{const data=await new Promise<string>((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result).split(",")[1]??"");fr.onerror=()=>reject(fr.error);fr.readAsDataURL(file)});await api("/api/v1/banner/conversations/"+conversation.conversation.id+"/messages",{method:"POST",body:JSON.stringify({type:"image",mediaMime:file.type,mediaBase64:data,message:""})});await refreshConversation()}catch(e){setChatError(e instanceof Error?e.message:"ارسال تصویر ناموفق بود")}finally{setImageBusy(false)}};
 useEffect(()=>()=>{if(timer.current)clearInterval(timer.current);const mr=recorder.current;if(mr&&mr.state!=="inactive"){mr.ondataavailable=null;mr.onstop=()=>mr.stream.getTracks().forEach(t=>t.stop());mr.stop()}},[]);
 if(conversation)return <div><button className="w-btn w-btn-ghost" onClick={()=>setConversation(null)}>بازگشت به پیام‌ها</button><div className="w-card" style={{padding:15,marginTop:10}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}><h3 style={{marginTop:0}}>{conversation.conversation.message||"گفت‌وگو"}</h3><span style={{fontSize:10,color:"var(--w-muted)"}}>{conversation.conversation.status==="closed"?"بایگانی‌شده":"فعال"}</span></div><div style={{display:"grid",gap:8,maxHeight:520,overflowY:"auto",padding:"8px 0"}}>{(conversation.messages??[]).map((m:any)=><div key={m.message_id} style={{padding:10,borderRadius:12,background:m.sender_identity_id===conversation.conversation.buyer_identity_id?"var(--w-card2)":"var(--w-surface)",border:"1px solid var(--w-border)",maxWidth:"88%",justifySelf:m.is_mine?"end":"start"}}>{m.message_type==="sticker"?<div style={{fontSize:38}}>{m.body}</div>:m.message_type==="offer"?<div><b>پیشنهاد قیمت</b><div style={{fontWeight:900,marginTop:5}}>{FA(Number(m.offer_amount??0).toLocaleString())} تومان</div></div>:m.media_mime?<BannerChatImage id={String(m.message_id)} mime={m.media_mime}/>:<div style={{whiteSpace:"pre-wrap"}}>{m.body}</div>}<div style={{fontSize:10,color:"var(--w-muted)",marginTop:5,display:"flex",gap:8,justifyContent:"flex-end"}}><span>{m.created_at?new Date(m.created_at).toLocaleTimeString("fa-IR",{hour:"2-digit",minute:"2-digit"}):""}</span>{m.is_mine&&<span>{m.read_at?"خوانده شد":"ارسال شد"}</span>}</div></div>)}</div>{chatError&&<div style={{color:"#dc2626",fontSize:12,marginTop:8}}>{chatError}</div>}<textarea className="w-input" value={text} onChange={e=>setText(e.target.value)} placeholder="پیام خود را بنویسید…" rows={3} style={{marginTop:10}}/><div style={{display:"flex",gap:8,marginTop:7,flexWrap:"wrap"}}><input id="banner-chat-image" type="file" accept="image/jpeg,image/png,image/webp" style={{display:"none"}} onChange={e=>{const f=e.target.files?.[0];if(f)void sendImage(f);e.currentTarget.value=""}}/><button className="w-btn w-btn-ghost" onClick={()=>document.getElementById("banner-chat-image")?.click()} disabled={imageBusy}>ارسال تصویر</button><button className="w-btn w-btn-ghost" onClick={()=>setShowStickers(v=>!v)}>شکلک‌ها</button><button className="w-btn w-btn-ghost" onClick={()=>setOfferMode(v=>!v)}>پیشنهاد قیمت</button><button className="w-btn w-btn-ghost" onClick={()=>recording?stopVoice():void startVoice()}>{recording?"پایان ضبط":"ضبط پیام صوتی"}</button><button className="w-btn w-btn-primary" onClick={()=>void send()} disabled={!text.trim()}>ارسال</button>{recording&&<><span style={{fontSize:12,color:"#dc2626",alignSelf:"center"}}>● ضبط {FA(recordingSecs)} ثانیه</span><button className="w-btn w-btn-ghost" onClick={cancelVoice}>لغو ضبط</button></>}</div>{showStickers&&<div className="w-card" style={{padding:10,display:"grid",gridTemplateColumns:"repeat(10,1fr)",gap:4,marginTop:8}}>{stickers.map(x=><button key={x} onClick={()=>void sendSticker(x)} style={{fontSize:22,border:0,background:"transparent",cursor:"pointer",padding:5}}>{x}</button>)}</div>}{offerMode&&<div style={{display:"flex",gap:8,marginTop:8}}><input className="w-input" inputMode="numeric" value={offerAmount} onChange={e=>setOfferAmount(EN(e.target.value).replace(/[^0-9]/g,""))} placeholder="مبلغ پیشنهادی به تومان"/><button className="w-btn w-btn-primary" onClick={()=>void sendOffer()} disabled={!offerAmount}>ثبت پیشنهاد</button></div>}</div></div>;
 return <div><h2>پیام‌ها و مکالمات</h2>{chatError&&<div style={{color:"#dc2626",fontSize:12}}>{chatError}</div>}{!conversations.length?<div className="w-card" style={{padding:30}}>گفت‌وگویی وجود ندارد.</div>:conversations.map(c=><button key={c.conversation_id} className="w-btn w-btn-ghost" onClick={()=>void open(c.conversation_id)} style={{width:"100%",justifyContent:"space-between",marginBottom:7}}><span style={{textAlign:"right"}}><b>{c.other_display_name??"کاربر آن بنر"}</b> · {c.last_message||"گفت‌وگو"}<small style={{display:"block",fontSize:10,color:"var(--w-muted)"}}>{c.last_message_at?new Date(c.last_message_at).toLocaleString("fa-IR"):""}</small></span><span style={{display:"flex",alignItems:"center",gap:7}}>{Number(c.unread_count)>0&&<b style={{background:"#059669",color:"#fff",borderRadius:99,padding:"2px 7px",fontSize:10}}>{FA(c.unread_count)}</b>}مشاهده</span></button>)}</div>;
}
function Tickets({tickets,ticket,setTicket,onRefresh}:{tickets:Ticket[];ticket:any;setTicket:(x:any)=>void;onRefresh:()=>void}){
 const [subject,setSubject]=useState("");const [message,setMessage]=useState("");const [reply,setReply]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 const subjects=["مشکل در ثبت آگهی","مشکل در پرداخت","سوال","درخواست حذف","گزارش تخلف","سایر"];
 const open=async(id:number)=>{setError("");try{setTicket(await api("/api/v1/banner/tickets/"+id))}catch(e){setError(e instanceof Error?e.message:"دریافت تیکت ناموفق بود")}};
 const create=async()=>{if(!subject||!message.trim())return;setBusy(true);setError("");try{const x=await api("/api/v1/banner/tickets",{method:"POST",body:JSON.stringify({subject,message:message.trim()})});setSubject("");setMessage("");onRefresh();if(x.ticket?.id)await open(Number(x.ticket.id))}catch(e){setError(e instanceof Error?e.message:"ثبت تیکت ناموفق بود")}finally{setBusy(false)}};
 const send=async()=>{if(!ticket?.ticket?.id||!reply.trim())return;setBusy(true);setError("");try{await api("/api/v1/banner/tickets/"+ticket.ticket.id+"/reply",{method:"POST",body:JSON.stringify({message:reply.trim()})});setReply("");await open(Number(ticket.ticket.id));onRefresh()}catch(e){setError(e instanceof Error?e.message:"ارسال پاسخ ناموفق بود")}finally{setBusy(false)}};
 return <div><h2>پشتیبانی آن بنر</h2><div className="w-card" style={{padding:16,marginBottom:14}}><b style={{fontSize:13}}>موضوع تیکت</b><div style={{display:"flex",gap:7,flexWrap:"wrap",margin:"10px 0"}}>{subjects.map(x=><button key={x} className={subject===x?"w-btn w-btn-primary":"w-btn w-btn-ghost"} onClick={()=>setSubject(x)} style={{fontSize:11}}>{x}</button>)}</div><textarea className="w-input" value={message} onChange={e=>setMessage(e.target.value)} placeholder="مشکل یا سوال خود را شرح دهید…" rows={4}/><button className="w-btn w-btn-primary" onClick={()=>void create()} disabled={busy||!subject||!message.trim()} style={{marginTop:8}}>{busy?"در حال ثبت…":"ارسال تیکت"}</button></div>{error&&<div className="w-card" style={{padding:10,color:"#dc2626",marginBottom:10}}>{error}</div>}{ticket?<div className="w-card" style={{padding:16,marginBottom:12}}><button className="w-btn w-btn-ghost" onClick={()=>setTicket(null)}>بازگشت به فهرست تیکت‌ها</button><h3>{ticket.ticket.subject}</h3><div style={{fontSize:11,color:"var(--w-muted)"}}>وضعیت: {ticket.ticket.status}</div><div style={{display:"grid",gap:8,marginTop:12}}>{(ticket.messages??[]).map((m:any)=><div key={m.id} style={{padding:10,borderRadius:10,background:m.sender_type==="user"?"var(--w-card2)":"var(--w-surface)",border:"1px solid var(--w-border)",maxWidth:"90%",justifySelf:m.sender_type==="user"?"end":"start"}}><div style={{fontSize:10,color:"var(--w-muted)",marginBottom:4}}>{m.sender_type==="admin"?"پشتیبانی":m.sender_type==="system"?"سامانه":"شما"}</div><div style={{whiteSpace:"pre-wrap",lineHeight:1.8}}>{m.body}</div><small style={{display:"block",textAlign:"left",fontSize:9,color:"var(--w-muted)",marginTop:5}}>{m.created_at?new Date(m.created_at).toLocaleString("fa-IR"):""}</small></div>)}</div><textarea className="w-input" value={reply} onChange={e=>setReply(e.target.value)} placeholder="پاسخ خود را بنویسید…" rows={3} style={{marginTop:12}}/><button className="w-btn w-btn-primary" onClick={()=>void send()} disabled={busy||!reply.trim()||ticket.ticket.status==="closed"} style={{marginTop:7}}>ارسال پاسخ</button></div>:null}<h3 style={{fontSize:14,marginTop:20}}>تیکت‌های ثبت‌شده</h3>{!tickets.length?<div className="w-card" style={{padding:24}}>تیکتی ثبت نشده است.</div>:tickets.map(t=><button key={t.id} className="w-btn w-btn-ghost" onClick={()=>void open(t.id)} style={{width:"100%",justifyContent:"space-between",marginBottom:7}}><span>#{FA(t.id)} · {t.subject}</span><span>{t.status==="open"?"باز":t.status==="pending"?"در انتظار پاسخ":t.status==="resolved"?"پاسخ داده شده":"بسته"}</span></button>)}</div>;
}
function LocalImagePreview({file}:{file:File}) {
  const canvas = useRef<HTMLCanvasElement | null>(null);
  useEffect(() => {
    let active = true;
    let bitmap: ImageBitmap | null = null;
    const drawPreview = async (): Promise<void> => {
      try {
        const image = await createImageBitmap(file);
        if (!active) {
          image.close();
          return;
        }
        bitmap = image;
        const target = canvas.current;
        if (!target) {
          return;
        }
        const context = target.getContext("2d");
        if (!context) {
          return;
        }
        const scale = Math.max(target.width / image.width, target.height / image.height);
        const sourceWidth = target.width / scale;
        const sourceHeight = target.height / scale;
        const sourceX = (image.width - sourceWidth) / 2;
        const sourceY = (image.height - sourceHeight) / 2;
        context.clearRect(0, 0, target.width, target.height);
        context.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, 0, 0, target.width, target.height);
      } catch {
        // Invalid or unsupported image files are rejected during selection and upload.
      }
    };
    void drawPreview();
    return () => {
      active = false;
      bitmap?.close();
    };
  }, [file]);
  return <canvas ref={canvas} width={188} height={140} aria-label="پیش‌نمایش تصویر" style={{width:94,height:74,objectFit:"cover",borderRadius:8,background:"var(--w-card2)"}} />;
};

function Post({categories,onDone}:{categories:any[];onDone:()=>void}){
 const [step,setStep]=useState(0);const [categoryId,setCategoryId]=useState("");const [title,setTitle]=useState("");const [contactEnabled,setContactEnabled]=useState(true);const [chatEnabled,setChatEnabled]=useState(true);const [description,setDescription]=useState("");const [price,setPrice]=useState("");const [priceMode,setPriceMode]=useState<"fixed"|"negotiable"|"free"|"swap">("fixed");const [condition,setCondition]=useState("used");const [provinceId,setProvinceId]=useState("tehran");const [cityId,setCityId]=useState("tehran");const [files,setFiles]=useState<File[]>([]);const [cropPosition,setCropPosition]=useState(50);const [attributes,setAttributes]=useState<Record<string,string>>({});const [busy,setBusy]=useState(false);const [err,setErr]=useState("");const [aiSuggestionId,setAiSuggestionId]=useState<number|null>(null);const [aiInfo,setAiInfo]=useState("");
 const options=categoryOptions(categories);const selectedCategory=options.find(x=>String(x.id)===categoryId);const province=IRAN_PROVINCES.find(x=>x.id===provinceId)??IRAN_PROVINCES[0];const cities=province?.cities??[];const selectedCity=cities.find(x=>x.id===cityId)??cities[0];
 const fieldsFor=(slug:string)=>{const id=String(slug??"");if(id.startsWith("re-"))return [["area","متراژ (متر مربع)","مثال: ۸۵"],["rooms","تعداد اتاق","مثال: ۲"],["year","سال ساخت","مثال: ۱۴۰۰"],["floor","طبقه","مثال: ۳"]];if(id.startsWith("veh-car")||id.startsWith("veh-pass"))return [["brand","برند","مثال: تویوتا"],["model","مدل","مثال: کمری"],["year","سال تولید","مثال: ۱۴۰۲"],["km","کارکرد (کیلومتر)","مثال: ۵۰٬۰۰۰"],["color","رنگ","مثال: سفید"]];if(id.startsWith("veh-moto"))return [["brand","برند","مثال: هوندا"],["year","سال تولید","مثال: ۱۴۰۲"],["km","کارکرد (کیلومتر)","مثال: ۸٬۰۰۰"]];if(id.startsWith("dig-mob"))return [["brand","برند","مثال: اپل"],["model","مدل","مثال: آیفون ۱۵ پرو مکس"],["storage","حافظه داخلی","مثال: ۲۵۶ گیگ"],["color","رنگ","مثال: مشکی"]];if(id.startsWith("dig-lap"))return [["brand","برند","مثال: ایسوس"],["cpu","پردازنده","مثال: Core i5"],["ram","رم","مثال: ۸ گیگ"],["storage","حافظه","مثال: SSD 512"]];if(id.startsWith("ent-book"))return [["author","نویسنده","مثال: داستایوفسکی"],["publisher","ناشر","مثال: نشر نی"],["year","سال چاپ","مثال: ۱۴۰۱"]];if(id.startsWith("job-"))return [["contract","نوع همکاری","مثال: تمام‌وقت"],["hours","ساعت کاری","مثال: ۸ تا ۵"],["salary","حقوق پیشنهادی","مثال: توافقی"]];if(id.startsWith("svc-"))return [["serviceType","نوع خدمت","مثال: نصب و راه‌اندازی"],["coverage","محدوده خدمت","مثال: تهران"],["experience","سابقه کار","مثال: ۵ سال"]];return [];};
 const dynamicFields=fieldsFor(selectedCategory?.slug??"");
 const suggest=async()=>{if(!title.trim()||!description.trim()||description.length>200)throw new Error("ابتدا عنوان و توضیحات آگهی را کامل کنید.");const r=await api("/api/v1/banner/ai/suggest",{method:"POST",body:JSON.stringify({title:title.trim(),description:description.trim()})});const x=r.suggestion;const id=Number(x.id);setAiSuggestionId(id);if(!categoryId&&x.categoryId)setCategoryId(String(x.categoryId));if(x.condition)setCondition(x.condition);if(x.price!==null&&x.price!==undefined&&!price)setPrice(String(x.price));if(x.attributes&&typeof x.attributes==="object"){const target=options.find(z=>String(z.id)===String(categoryId||x.categoryId));const allowed=fieldsFor(target?.slug??"").map(z=>z[0]);const filtered=Object.fromEntries(Object.entries(x.attributes).filter(([key])=>allowed.includes(key)).map(([key,value])=>[key,String(value)]));setAttributes(old=>Object.keys(old).length?old:filtered);}setAiInfo("پیشنهاد هوشمند دریافت شد؛ دسته‌بندی و ویژگی‌ها قابل ویرایش هستند.");return id;};
 const next=async()=>{setErr("");if(step===0){if(!files.length){setErr("حداقل یک تصویر برای آگهی انتخاب کنید.");return;}if(!title.trim()||!description.trim()||description.length>200){setErr("عنوان و توضیحات الزامی است و توضیحات باید حداکثر ۲۰۰ کاراکتر باشد.");return;}setBusy(true);try{if(!aiSuggestionId)await suggest();setStep(1)}catch(e){setErr(e instanceof Error?e.message:"پیشنهاد هوشمند در دسترس نیست؛ دوباره تلاش کنید.")}finally{setBusy(false)}return;}if(step===1){if(!categoryId||!selectedCity){setErr("دسته‌بندی و شهر را انتخاب کنید.");return;}setStep(2)}};
 const cropFile=async(file:File)=>{const bitmap=await createImageBitmap(file);const target=4/3;let sw=bitmap.width,sh=bitmap.height,sx=0,sy=0;if(sw/sh>target){sw=sh*target;sx=(bitmap.width-sw)*(cropPosition/100)}else{sh=sw/target;sy=(bitmap.height-sh)*.5}const canvas=document.createElement("canvas");canvas.width=1200;canvas.height=900;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("image_crop_unavailable");ctx.drawImage(bitmap,sx,sy,sw,sh,0,0,1200,900);bitmap.close();const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error("image_crop_failed")),"image/jpeg",.9));return new File([blob],file.name.replace(/\.[^.]+$/,"")+".jpg",{type:"image/jpeg"})};
 const submit=async()=>{if(!files.length||!title.trim()||!description.trim()||description.length>200||!selectedCategory||!selectedCity||(!contactEnabled&&!chatEnabled)||priceMode==="fixed"&&!price.trim()){setErr("اطلاعات مراحل قبل را بررسی کنید؛ حداقل یک تصویر و یک روش تماس الزامی است.");return;}if(files.some(x=>x.size>15*1024*1024)){setErr("حجم هر تصویر باید حداکثر ۱۵ مگابایت باشد.");return;}setBusy(true);setErr("");let createdId:string|null=null;try{let suggestionId=aiSuggestionId;if(!suggestionId)suggestionId=await suggest();const numericPrice=priceMode==="fixed"?Number(EN(price).replace(/[^0-9]/g,"")):null;if(priceMode==="fixed"&&(!Number.isFinite(numericPrice)||numericPrice===null||numericPrice<0))throw new Error("قیمت واردشده معتبر نیست.");const x=await api("/api/v1/banner/listings",{method:"POST",body:JSON.stringify({categoryId:Number(categoryId),aiSuggestionId:suggestionId,title:title.trim(),description:description.trim(),price:numericPrice,priceMode,condition,city:selectedCity.name,currency:"IRR",attributes,contactEnabled,chatEnabled})});createdId=String(x.listing.id);for(const original of files.slice(0,8)){const file=await cropFile(original);const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(",")[1]??"");r.onerror=()=>reject(r.error);r.readAsDataURL(file)});await api("/api/v1/banner/listings/"+createdId+"/media",{method:"POST",body:JSON.stringify({mimeType:file.type,filename:file.name,dataBase64:data})})}onDone()}catch(e){if(createdId)await api("/api/v1/banner/listings/"+encodeURIComponent(createdId),{method:"DELETE"}).catch(()=>{});setErr(e instanceof Error?e.message:"ثبت آگهی ناموفق بود")}finally{setBusy(false)}};
 const steps=["تصویر و توضیحات","دسته‌بندی و شهر","قیمت و ارسال"];
 const pickFiles=(list:FileList|null)=>{if(!list)return;const chosen=Array.from(list).slice(0,8);if(chosen.some(x=>!["image/jpeg","image/png","image/webp"].includes(x.type))){setErr("فقط تصویر JPG، PNG یا WebP مجاز است.");return;}if(chosen.some(x=>x.size>15*1024*1024)){setErr("حجم هر تصویر باید حداکثر ۱۵ مگابایت باشد.");return;}setFiles(chosen);setErr("")};
 return <div className="w-card" style={{padding:22,maxWidth:820}}><h2 style={{marginTop:0}}>ثبت آگهی</h2><p style={{color:"var(--w-muted)",fontSize:12,lineHeight:1.8}}>اطلاعات آگهی را در سه مرحله تکمیل کنید. پس از ثبت، آگهی برای بررسی مدیریت ارسال می‌شود.</p><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:7,margin:"16px 0"}}>{steps.map((x,i)=><div key={x} style={{padding:9,borderRadius:9,background:i===step?"rgba(0,214,176,.1)":"var(--w-card2)",border:"1px solid "+(i===step?"var(--w-accent,var(--w-border))":"var(--w-border)"),fontSize:11,textAlign:"center",fontWeight:i===step?800:500}}>{FA(i+1)}. {x}</div>)}</div>
 {step===0&&<div style={{display:"grid",gap:11}}><div><b style={{fontSize:12}}>تصاویر آگهی (حداکثر ۸ تصویر)</b><input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>{pickFiles(e.target.files);e.currentTarget.value=""}} style={{display:"block",marginTop:8,fontSize:12}}/><div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:9}}>{files.map((x,i)=><div key={i} style={{width:94}}><LocalImagePreview file={x}/><button className="w-btn w-btn-ghost" onClick={()=>setFiles(p=>p.filter((_,n)=>n!==i))} style={{width:"100%",marginTop:4,fontSize:10}}>حذف تصویر</button></div>)}</div>{files.length>0&&<label style={{display:"block",fontSize:11,color:"var(--w-muted)",marginTop:10}}>موقعیت افقی برش تصویر: {FA(cropPosition)}٪<input type="range" min="0" max="100" value={cropPosition} onChange={e=>setCropPosition(Number(e.target.value))} style={{width:"100%"}}/></label>}</div><label style={{fontSize:12,fontWeight:700}}>عنوان آگهی<input className="w-input" value={title} onChange={e=>{setTitle(e.target.value);setAiSuggestionId(null)}} maxLength={100} placeholder="مثلاً: آیفون ۱۵ پرو مکس" style={{marginTop:6}}/></label><label style={{fontSize:12,fontWeight:700}}>توضیحات<textarea className="w-input" value={description} onChange={e=>{setDescription(e.target.value.slice(0,200));setAiSuggestionId(null)}} maxLength={200} rows={4} placeholder="حداکثر ۲۰۰ کاراکتر" style={{marginTop:6}}/></label><div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:"var(--w-muted)"}}><span>توضیحات آگهی</span><span>{FA(description.length)}/۲۰۰</span></div><button className="w-btn w-btn-ghost" onClick={()=>{setBusy(true);setErr("");void suggest().catch(e=>setErr(e instanceof Error?e.message:"banner_ai_failed")).finally(()=>setBusy(false))}} disabled={busy||!title.trim()||!description.trim()}>تحلیل هوشمند و پیشنهاد دسته‌بندی</button>{aiInfo&&<span style={{fontSize:11,color:"#059669"}}>{aiInfo}</span>}</div>}
 {step===1&&<div style={{display:"grid",gap:11}}><label style={{fontSize:12,fontWeight:700}}>دسته‌بندی<select className="w-input" value={categoryId} onChange={e=>{setCategoryId(e.target.value);setAttributes({})}} style={{marginTop:6}}><option value="">انتخاب دسته‌بندی</option>{options.map(x=><option key={x.id} value={String(x.id)}>{"— ".repeat(x._depth)}{x.name}</option>)}</select></label>{dynamicFields.length>0&&<div className="w-card" style={{padding:13,background:"var(--w-card2)"}}><b style={{fontSize:12}}>ویژگی‌های دسته‌بندی</b><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:8,marginTop:10}}>{dynamicFields.map(([key,label,placeholder])=><label key={key} style={{fontSize:11}}>{label}<input className="w-input" value={attributes[key]??""} onChange={e=>setAttributes(p=>({...p,[key]:e.target.value}))} placeholder={placeholder} style={{marginTop:5}}/></label>)}</div></div>}<label style={{fontSize:12,fontWeight:700}}>استان<select className="w-input" value={provinceId} onChange={e=>{const p=IRAN_PROVINCES.find(x=>x.id===e.target.value);setProvinceId(e.target.value);setCityId(p?.cities[0]?.id??"")}} style={{marginTop:6}}>{IRAN_PROVINCES.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label style={{fontSize:12,fontWeight:700}}>شهر<select className="w-input" value={cityId} onChange={e=>setCityId(e.target.value)} style={{marginTop:6}}>{cities.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div>}
 {step===2&&<div style={{display:"grid",gap:12}}><div><b style={{fontSize:12}}>نوع قیمت</b><div className="ab-price-modes" style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:7,marginTop:7}}>{([{key:"fixed",label:"ثابت"},{key:"negotiable",label:"توافقی"},{key:"free",label:"رایگان"},{key:"swap",label:"معاوضه"}] as const).map(x=><button key={x.key} type="button" className={priceMode===x.key?"w-btn w-btn-primary":"w-btn w-btn-ghost"} onClick={()=>setPriceMode(x.key)} style={{justifyContent:"center",fontSize:11}}>{x.label}</button>)}</div>{priceMode==="fixed"&&<input className="w-input" value={price} onChange={e=>setPrice(EN(e.target.value).replace(/[^0-9]/g,""))} placeholder="قیمت به تومان" inputMode="numeric" style={{marginTop:8}}/>}</div><label style={{fontSize:12,fontWeight:700}}>وضعیت کالا<select className="w-input" value={condition} onChange={e=>setCondition(e.target.value)} style={{marginTop:6}}><option value="new">نو</option><option value="like-new">در حد نو</option><option value="good">خوب</option><option value="used">کارکرده</option><option value="for-parts">قطعات</option></select></label><div style={{display:"flex",gap:14,flexWrap:"wrap",fontSize:12}}><label><input type="checkbox" checked={contactEnabled} onChange={e=>setContactEnabled(e.target.checked)}/> تماس تلفنی</label><label><input type="checkbox" checked={chatEnabled} onChange={e=>setChatEnabled(e.target.checked)}/> پیام و چت</label></div><div style={{padding:12,borderRadius:10,background:"var(--w-card2)",fontSize:12,lineHeight:1.9}}><b>خلاصه آگهی</b><div>{title} · {selectedCategory?.name} · {selectedCity?.name}</div><div>{fmt(priceMode==="fixed"?Number(EN(price)):null,"IRR",priceMode)}</div></div></div>}
 {err&&<div style={{color:"#dc2626",fontSize:12,marginTop:12}}>{err}</div>}<div style={{display:"flex",justifyContent:"space-between",gap:8,marginTop:18}}>{step>0?<button className="w-btn w-btn-ghost" onClick={()=>{setErr("");setStep(x=>Math.max(0,x-1))}} disabled={busy}>مرحله قبل</button>:<span/>}{step<2?<button className="w-btn w-btn-primary" onClick={()=>void next()} disabled={busy}>{busy?"در حال تحلیل…":"ادامه"}</button>:<button className="w-btn w-btn-primary" onClick={()=>void submit()} disabled={busy}>{busy?"در حال ثبت و بارگذاری…":"ثبت آگهی برای بررسی"}</button>}</div></div>;
}
function SearchPanel({history,query,setQuery,onSearch,onClear}:{history:string[];query:string;setQuery:(v:string)=>void;onSearch:(value?:string)=>void;onClear:()=>void}){
 return <div className="w-card" style={{padding:22,maxWidth:820}}><h2 style={{marginTop:0}}>جستجو در همه آگهی‌ها</h2><div style={{display:"flex",gap:8}}><input className="w-input" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&onSearch()} placeholder="نام کالا، خدمت یا عبارت موردنظر"/><button className="w-btn w-btn-primary" onClick={()=>onSearch()}>جستجو</button></div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:22}}><b>جستجوهای اخیر</b><button className="w-btn w-btn-ghost" onClick={onClear} disabled={!history.length}>حذف همه</button></div>{history.length?<div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:10}}>{history.map((x,i)=><button key={i} className="w-btn w-btn-ghost" onClick={()=>{setQuery(x);onSearch(x)}}>{x}</button>)}</div>:<p style={{color:"var(--w-muted)",fontSize:13}}>هنوز جستجویی ذخیره نشده است.</p>}</div>;
}
function Postchi({items,onRefresh,onOpenListing,onOpenConversation}:{items:any[];onRefresh:()=>void;onOpenListing:(id:string)=>void;onOpenConversation:(id:string)=>void}){
 const [busy,setBusy]=useState(false);const unread=items.filter(x=>!x.read).length;
 const mark=async(source:string,id:string)=>{try{await api("/api/v1/banner/postchi/"+source+"/"+encodeURIComponent(id)+"/read",{method:"PATCH",body:"{}"});onRefresh()}catch{}};
 const markAll=async()=>{setBusy(true);try{await api("/api/v1/banner/postchi/read-all",{method:"POST",body:"{}"});onRefresh()}finally{setBusy(false)}};
 const title=(x:any)=>({listing_created:"ثبت آگهی",listing_updated:"ویرایش آگهی",message_sent:"ارسال پیام",conversation_created:"ایجاد گفت‌وگو",inquiry_created:"درخواست گفت‌وگو",inquiry_reply:"پاسخ گفت‌وگو",profile_update:"به‌روزرسانی پروفایل",seller_contact_viewed:"نمایش اطلاعات تماس",ai_listing_suggestion:"پیشنهاد هوشمند آگهی"}[x.type]??x.title??"رویداد آن بنر");
 return <div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}><div><h2 style={{margin:"0 0 4px"}}>پستچی آن بنر</h2><span style={{fontSize:11,color:"var(--w-muted)"}}>{FA(unread)} رویداد خوانده‌نشده</span></div><button className="w-btn w-btn-ghost" onClick={()=>void markAll()} disabled={busy||!unread}>خواندن همه</button></div>{!items.length?<div className="w-card" style={{padding:30,marginTop:12}}>هنوز رویدادی ثبت نشده است.</div>:items.map(x=><button key={x.source+":"+x.event_id} onClick={()=>{void mark(x.source,String(x.event_id));if(x.resource_type==="listing"&&x.resource_id)onOpenListing(String(x.resource_id));else if(x.resource_type==="inquiry"&&x.resource_id)onOpenConversation(String(x.resource_id))}} className="w-card" style={{width:"100%",display:"flex",alignItems:"flex-start",gap:12,padding:14,marginTop:8,textAlign:"right",border:"1px solid var(--w-border)",background:x.read?"var(--w-card)":"var(--w-card2)",cursor:"pointer"}}><span style={{width:38,height:38,borderRadius:12,background:"var(--w-card2)",display:"grid",placeItems:"center",flexShrink:0}}>{x.type==="message"||x.type==="message_sent"?"✉":x.type==="listing_created"?"＋":x.type==="offer"?"↔":"◉"}</span><span style={{flex:1,minWidth:0}}><b style={{display:"block",fontSize:13}}>{title(x)}</b><small style={{display:"block",fontSize:11,color:"var(--w-muted)",lineHeight:1.8,marginTop:4}}>{x.description}</small><small style={{display:"block",fontSize:10,color:"var(--w-muted)",marginTop:5}}>{x.created_at?new Date(x.created_at).toLocaleString("fa-IR"):""}</small></span>{!x.read&&<i style={{width:8,height:8,borderRadius:99,background:"#059669",marginTop:5,flexShrink:0}}/>}</button>)}</div>;
}
function SupportInfo(){return <div className="w-card" style={{padding:28,maxWidth:680,textAlign:"center"}}><div style={{width:84,height:84,borderRadius:24,background:"rgba(232,53,78,.1)",display:"grid",placeItems:"center",margin:"0 auto 20px",fontSize:38}}>🎧</div><h2 style={{margin:"0 0 10px"}}>پشتیبانی آن بنر</h2><p style={{color:"var(--w-muted)",fontSize:13,lineHeight:2,margin:"0 auto 22px"}}>برای ارتباط مستقیم با تیم پشتیبانی با شماره زیر تماس بگیرید. همچنین از بخش تیکت‌های پشتیبانی می‌توانید درخواست خود را ثبت و پیگیری کنید.</p><a href="tel:09375437106" className="w-btn w-btn-primary" style={{display:"inline-flex",alignItems:"center",gap:10,textDecoration:"none",direction:"ltr",fontSize:18,padding:"13px 22px"}}>☎ ۰۹۳۷۵۴۳۷۱۰۶</a><div style={{fontSize:11,color:"var(--w-muted)",marginTop:12}}>برای تماس، روی شماره بزنید.</div></div>}
function TermsInfo(){const sections=[{title:"۱. شرایط عمومی",body:"با استفاده از سرویس آن بنر، کاربر می‌پذیرد که تمام مقررات این سند را رعایت کند. آن بنر یک بازار آنلاین آگهی‌های ایران است و هیچ‌گونه مسئولیتی در قبال معاملات بین طرفین ندارد."},{title:"۲. قوانین ثبت آگهی",body:"آگهی‌ها باید دقیق، صادقانه و غیرمضر باشند. ثبت آگهی‌های تقلبی، فریبکارانه، یا غیرقانونی ممنوع است. آن بنر حق حذف یا ویرایش هر آگهی را برای خود محفوظ می‌دارد."},{title:"۳. حریم خصوصی",body:"اطلاعات شخصی کاربران با بالاترین استانداردهای امنیتی نگهداری می‌شود. اطلاعات هیچ‌گاه بدون رضایت کاربر به اشخاص ثالث داده نمی‌شود، مگر در موارد الزامی قانونی."},{title:"۴. مسئولیت‌پذیری",body:"آن بنر صرفاً یک بستر آگهی است. هرگونه تراکنش مالی، تحویل کالا، و ضمانت کیفیت بر عهده طرفین معامله است. توصیه می‌شود معاملات حضوری انجام شوند."},{title:"۵. مالکیت معنوی",body:"تمامی محتوای آن بنر شامل نشانه‌های تجاری، طراحی و کدهای نرم‌افزاری تحت حمایت قوانین مالکیت معنوی هستند و استفاده غیرمجاز از آن‌ها ممنوع است."},{title:"۶. تغییرات مقررات",body:"آن بنر حق دارد در هر زمان این مقررات را تغییر دهد. ادامه استفاده از سرویس پس از تغییرات به منزله پذیرش مقررات جدید است. کاربران از طریق ایمیل مطلع خواهند شد."}];return <div className="w-card" style={{padding:22,maxWidth:820}}><h2 style={{marginTop:0}}>قوانین و مقررات آن بنر</h2><p style={{fontSize:12,color:"var(--w-muted)",lineHeight:1.9,borderBottom:"1px solid var(--w-border)",paddingBottom:14}}>آخرین بروزرسانی: ۱۴۰۳/۰۶/۰۱ · لطفاً پیش از استفاده از سرویس آن بنر این مقررات را به دقت مطالعه کنید.</p>{sections.map((x,i)=><section key={i} style={{padding:"14px 0",borderBottom:"1px solid var(--w-border)"}}><h3 style={{fontSize:14,margin:"0 0 8px"}}>{x.title}</h3><p style={{fontSize:12,color:"var(--w-muted)",lineHeight:2,margin:0}}>{x.body}</p></section>)}<div style={{marginTop:14,padding:13,borderRadius:10,background:"var(--w-card2)",fontSize:12,color:"var(--w-muted)",lineHeight:1.9}}>با استفاده از آن بنر، تمامی شرایط فوق را پذیرفته‌اید. برای پرسش‌های بیشتر با پشتیبانی تماس بگیرید.</div></div>}

function SellerProfile({identityId,onOpenListing,onBack}:{identityId:string;onOpenListing:(x:Listing)=>void;onBack:()=>void}){
 const [data,setData]=useState<any|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState("");
 useEffect(()=>{let active=true;setLoading(true);api("/api/v1/banner/users/"+encodeURIComponent(identityId)+"/profile").then(x=>{if(active)setData(x)}).catch(e=>{if(active)setError(e instanceof Error?e.message:"seller_profile_failed")}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[identityId]);
 const profile=data?.profile??{};
 return <div><button className="w-btn w-btn-ghost" onClick={onBack}>بازگشت</button>{loading?<div className="w-card" style={{padding:24,marginTop:10}}>در حال دریافت پروفایل فروشنده…</div>:error?<div className="w-card" style={{padding:24,marginTop:10,color:"#dc2626"}}>{error}</div>:<><div className="w-card" style={{padding:24,marginTop:10,display:"flex",alignItems:"center",gap:15}}>{profile.avatar_data_url?<img src={profile.avatar_data_url} alt="" style={{width:76,height:76,borderRadius:22,objectFit:"cover"}}/>:<span style={{width:76,height:76,borderRadius:22,background:"var(--w-card2)",display:"grid",placeItems:"center"}}><WI n="user" s={32}/></span>}<div><h2 style={{margin:"0 0 5px"}}>{profile.display_name??"کاربر آن بنر"}</h2><div style={{fontSize:12,color:"var(--w-muted)"}}>{profile.city??"موقعیت ثبت نشده"} · عضو از {profile.created_at?new Date(profile.created_at).toLocaleDateString("fa-IR"):"—"}</div><b style={{fontSize:12,display:"block",marginTop:7}}>{FA(data.listings?.length??0)} آگهی فعال</b></div></div><h3 style={{margin:"18px 0 10px"}}>آگهی‌های فعال فروشنده</h3><Home listings={data.listings??[]} loading={false} favorites={new Set()} onOpen={onOpenListing} onFavorite={()=>{}}/></>}</div>;
}
